    var xforms = [["id", 0.0, function (g) { return g; }]], i, j, k, x;
    for (i = 1; i < G.DIHEDRAL.length; i++) xforms.push([G.DIHEDRAL[i][0], 0.5, G.DIHEDRAL[i][1]]);
